function insertChart(c:ChartSummary){if(replacing.value && selected.value){flush();selected.value.chartId=c.id;selected.value.componentType=addingType.value;selected.value.content=undefined;selected.value.chartConfig=undefined;flush();refreshPanel(selected.value.key)}else{const p=basePanel(addingType.value);p.chartId=c.id;p.title=addingType.value==='kpi'?c.name+' · 汇总':c.name;insert(p)}chartDialog.value=false}
function duplicate(){if(!chosen.value.length || busy.value || hasLocked.value)return;if(chosen.value.some(p=>p.parentKey && !selectedKeys.value.includes(p.parentKey))){ElMessage.warning('请复制整个容器，或先移出成员');return}if(document.panels.length+chosen.value.length>20){ElMessage.warning('复制后组件不能超过20个');return}const staged=[...document.panels],copies:Panel[]=[],copyGroups=new Map<string,string>(),copyKeys=new Map(chosen.value.map(p=>[p.key,crypto.randomUUID()]));const copyDx=screen.value?Math.min(32,bounds.value.width-Math.max(...chosen.value.map(p=>p.x+p.w))):0,copyDy=screen.value?Math.min(32,bounds.value.height-Math.max(...chosen.value.map(p=>p.y+p.h))):0;for(const original of chosen.value){const copy=JSON.parse(JSON.stringify(original)) as Panel;copy.key=copyKeys.get(original.key)!;if(copy.parentKey)copy.parentKey=copyKeys.get(copy.parentKey);if(copy.groupKey){if(!copyGroups.has(copy.groupKey))copyGroups.set(copy.groupKey,crypto.randomUUID());copy.groupKey=copyGroups.get(copy.groupKey)}copy.title=copy.title.slice(0,195)+' 副本';copy.locked=false;let placed=false;if(screen.value){const p={...copy,x:copy.x+copyDx,y:copy.y+copyDy};if(validLayout([...staged,p],bounds.value)){staged.push(p);copies.push(p);placed=true}}else for(let y=0;y<=120-copy.h && !placed;y++)for(let x=0;x<=12-copy.w && !placed;x++){const p={...copy,x,y};if(validLayout([...staged,p],bounds.value)){staged.push(p);copies.push(p);placed=true}}if(!placed){ElMessage.warning('画布空间不足，未复制任何组件');return}}try{validateContainerLayout(staged,document.kind)}catch{ElMessage.warning('复制后的容器关系无效');return}flush();document.panels=staged;selectedKeys.value=copies.map(p=>p.key);selectedKey.value=copies.find(p=>p.componentType==='container')?.key || selectedKeys.value.at(-1) || '';flush();if(copies.some(p=>p.chartId))refreshAll();ElMessage.info('已复制所选组件；筛选与联动可另行绑定')}
async function removePanel(key:string){return removeKeys([key])}
async function removeKeys(keys:string[]){keys=expandedSelection(document.panels,keys);if(busy.value || document.panels.some(p=>keys.includes(p.key) && p.locked)){ElMessage.warning('请先解锁组件');return}const set=new Set(keys),interaction=document.interaction;const used=interaction && (interaction.controls.some(c=>c.targets.some(t=>set.has(t.panel))) || interaction.links.some(l=>set.has(l.sourcePanel) || l.targets.some(t=>set.has(t.panel))));if(used){try{await ElMessageBox.confirm('删除所选组件会同步清理相关筛选和联动，可通过撤销恢复。','删除已绑定组件',{type:'warning'})}catch{return}}flush();document.panels=document.panels.filter(p=>!set.has(p.key));if(interaction){interaction.controls=interaction.controls.map(c=>({...c,targets:c.targets.filter(t=>!set.has(t.panel))})).filter(c=>c.targets.length);interaction.links=interaction.links.filter(l=>!set.has(l.sourcePanel)).map(l=>({...l,targets:l.targets.filter(t=>!set.has(t.panel))})).filter(l=>l.targets.length)}for(const key of keys){delete payloads[key];delete panelErrors[key]}clearSelection();flush()}
