function changeGeometry(key:'x'|'y'|'w'|'h',value:number){containerFormVersion.value++;if(!selected.value || selected.value.locked || !Number.isInteger(value))return;const current=selected.value;if(current.componentType==='container' && (key==='x' || key==='y')){layoutCommand(()=>movePanels(document.panels,expandedSelection(document.panels,[current.key]),key==='x'?value-current.x:0,key==='y'?value-current.y:0,bounds.value));return}const p={...current,[key]:value},next=document.panels.map(v=>v.key===p.key?p:v);if(!validLayout(next,bounds.value)){ElMessage.warning('组件不能重叠或超出画布边界');return}layoutCommand(()=>next)}
