async function applyImage(key:string,image:string){const p=document.panels.find(p=>p.key===key);if(!p || p.componentType!=='image' || p.locked || busy.value)return;const content={image},test=JSON.parse(snapshot());test.panels.find((v:Panel)=>v.key===key).content=content;if(JSON.stringify(test).length>1048576){ElMessage.warning('看板文档超过 1MB，请减少图片大小');return}flush();p.content=content;flush()}
async function uploadImage(event:Event){const input=event.target as HTMLInputElement,file=input.files?.[0],key=selectedKey.value;input.value='';if(!file || !selected.value || busy.value)return;if(file.size>262144 || !['image/png','image/jpeg','image/webp'].includes(file.type)){ElMessage.warning('请选择 256KB 以内的 PNG/JPEG/WebP 图片');return}const dataUrl=await new Promise<string>((resolve,reject)=>{const reader=new FileReader();reader.onload=()=>resolve(String(reader.result));reader.onerror=reject;reader.readAsDataURL(file)});const p=document.panels.find(p=>p.key===key);if(!p || p.componentType!=='image')return;if(checkPermi(['bi:asset:add','bi:dashboard:edit','bi:dashboard:add'])){try{const r=(await uploadStagingAsset(dataUrl,file.name.slice(0,200))).data;trackStagingAsset(r.id);applyImage(key,r.image);return}catch{/* 回退为仅本地嵌入 */}}applyImage(key,dataUrl)}
function applyChartConfig(key:string,config:PanelChartConfig|undefined,payload:PanelResult){const p=document.panels.find(p=>p.key===key);if(!p || p.locked || busy.value)return;flush();p.chartConfig=config;flush();requests[key]=(requests[key]||0)+1;panelLoading[key]=false;delete panelErrors[key];payloads[key]=payload;if(document.interaction?.links.some(l=>l.sourcePanel===key && config && l.sourceField!==config.dimensions[0]?.field))ElMessage.warning('组件维度已变更，请在“筛选与联动”中更新来源字段后保存')}
async function refreshPanel(key:string){const p=document.panels.find(p=>p.key===key);if(!p?.chartId || p.hidden)return;const e=epoch,v=(requests[key]||0)+1;requests[key]=v;panelLoading[key]=true;delete panelErrors[key];delete payloads[key];try{const result=(await previewDashboard({schemaVersion:1,name:document.name || '组件预览',kind:document.kind,layout:document.layout,scene:document.scene,panels:[{...JSON.parse(JSON.stringify(p)),groupKey:undefined,parentKey:undefined}],interaction:{controls:[],links:[]}},{filters:{},links:{}},id.value,version.value)).data;if(e!==epoch || requests[key]!==v || !document.panels.some(p=>p.key===key && !p.hidden))return;payloads[key]=result.payloads[key]}catch(err){if(e===epoch && requests[key]===v)panelErrors[key]=err instanceof Error?err.message:'图表加载失败，请检查权限或数据源'}finally{if(e===epoch && requests[key]===v)panelLoading[key]=false}}
