async function togglePreview(){flush();++epoch;preview.value=!preview.value;for(const key of Object.keys(panelLoading))panelLoading[key]=false}
async function save(){if(!document.name.trim()){ElMessage.warning('请填写看板名称');return false}flush();saving.value=true;error.value='';try{const copy=normalizeDashboard(JSON.parse(snapshot()));copy.name=copy.name.trim();const r=(await saveDashboard(copy,id.value,version.value)).data;if(!id.value)resourceActions.value=['edit','publish','consume'];id.value=r.id;version.value=r.version;Object.assign(document,copy);baseline.value=snapshot();savedAt.value=new Date().toLocaleTimeString('zh-CN',{hour12:false});if(!route.params.id)await router.replace('/bi-admin/dashboard-workspace/'+r.id+'/edit');await flushStagingAssets();ElMessage.success('草稿已保存');return true}catch{error.value='保存失败，请检查组件内容、字段权限或版本冲突后重试';return false}finally{saving.value=false}}
async function publish(){try{await ElMessageBox.confirm('将保存并发布当前看板，替换查看端的发布版本。','发布看板',{type:'warning'})}catch{return}if(dirty.value || !id.value){if(!await save())return}saving.value=true;try{const r=(await publishDashboard(id.value!,version.value!)).data;version.value=r.version;ElMessage.success('发布成功，可返回列表查看已发布看板')}catch{error.value='发布失败，请检查图片/文本是否完整及图表权限；若版本冲突请重新打开'}finally{saving.value=false}}
function closeInteraction(done:()=>void){flush();done()}
async function discard(){if(!dirty.value)return true;try{await ElMessageBox.confirm('当前草稿尚未保存，是否放弃修改？','未保存的修改',{type:'warning'});return true}catch{return false}}
