function beforeUnload(event:BeforeUnloadEvent){if(dirty.value){event.preventDefault();event.returnValue=''}}
function keyboard(event:KeyboardEvent){const target=event.target as HTMLElement;if(target.closest('input,textarea,select,[contenteditable="true"],.viewport-tools,.guide-list,.guide,.el-dialog,.el-drawer,.el-message-box,[role="dialog"]') || preview.value || busy.value)return;const mod=event.ctrlKey || event.metaKey,key=event.key.toLowerCase();if(selectedKeys.value.length>1 && !mod && ['arrowleft','arrowright','arrowup','arrowdown'].includes(key)){event.preventDefault();const step=event.shiftKey?5:1;moveSelected(key==='arrowleft'?-step:key==='arrowright'?step:0,key==='arrowup'?-step:key==='arrowdown'?step:0);return}if(mod && key==='a'){event.preventDefault();selectAll();return}if(key==='escape'){clearSelection();return}if(mod && key==='z'){event.preventDefault();event.shiftKey?redo():undo()}else if(mod && key==='y'){event.preventDefault();redo()}else if(mod && key==='d' && selected.value){event.preventDefault();duplicate()}else if((key==='delete' || key==='backspace') && selected.value){event.preventDefault();removeSelected()}}
onMounted(async()=>{media=window.matchMedia('(max-width: 980px)');syncNarrow();media.addEventListener('change',syncNarrow);window.addEventListener('keydown',keyboard);window.addEventListener('beforeunload',beforeUnload);try{const existing=route.params.id;if(!checkPermi([existing?'bi:dashboard:edit':'bi:dashboard:add']))throw new Error('没有看板设计权限');if(existing){const d=(await getDashboardDraft(Number(existing))).data;id.value=d.id;version.value=d.version;resourceActions.value=d.resourceActions || [];Object.assign(document,normalizeDashboard(d.definition))}charts.value=checkPermi(['bi:chart:list'])?((await listCharts()).data || []).filter(c=>c.resourceActions.includes('query')):[];await nextTick();baseline.value=snapshot();history.reset(snapshot());historyTick.value++;initializing.value=false;await refreshAll()}catch(err){initializing.value=false;loadFailed.value=true;baseline.value=snapshot();error.value=err instanceof Error?err.message:'看板加载失败'}})
onBeforeUnmount(()=>{++epoch;if(timer)clearTimeout(timer);media?.removeEventListener('change',syncNarrow);window.removeEventListener('keydown',keyboard);window.removeEventListener('beforeunload',beforeUnload);void flushStagingAssets()})
</script>
